ALTER TABLE invoices ADD COLUMN IF NOT EXISTS client_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS project_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS tax_rate DECIMAL(6,3) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS tax_amount DECIMAL(15,2) NOT NULL DEFAULT 0;
ALTER TABLE invoice_payments ADD COLUMN IF NOT EXISTS lead_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS reference VARCHAR(150) NULL, ADD COLUMN IF NOT EXISTS gateway VARCHAR(50) NOT NULL DEFAULT 'manual', ADD COLUMN IF NOT EXISTS currency VARCHAR(10) NOT NULL DEFAULT 'USD', ADD COLUMN IF NOT EXISTS status ENUM('pending','successful','failed','refunded') NOT NULL DEFAULT 'successful', ADD COLUMN IF NOT EXISTS gateway_transaction_id VARCHAR(150) NULL, ADD COLUMN IF NOT EXISTS metadata JSON NULL;
CREATE TABLE IF NOT EXISTS invoice_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(80) NOT NULL,description TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_invoice_event(invoice_id),CONSTRAINT fk_invoice_event_v9 FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoice_payment_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,gateway VARCHAR(50) NOT NULL,reference VARCHAR(150) NOT NULL UNIQUE,amount DECIMAL(15,2) NOT NULL,currency VARCHAR(10) NOT NULL,status ENUM('initiated','successful','failed','cancelled') NOT NULL DEFAULT 'initiated',gateway_transaction_id VARCHAR(150) NULL,metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_attempt_invoice(invoice_id),CONSTRAINT fk_attempt_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoice_reminders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,reminder_type ENUM('upcoming_due','overdue') NOT NULL,sent_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_invoice_reminder(invoice_id,reminder_type,DATE(sent_at)),CONSTRAINT fk_reminder_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;